        $leg = $canal === 'threads' ? mb_substr(explode("\n\n#", $c['caption'])[0], 0, 480) : $c['caption'];
        $ins->execute([$canal, 'carousel', $canal === 'threads' ? 'imagem' : 'video', $leg, $urls[0], $json, $when, 'pendente', null]);
        $out[] = strtoupper($canal) . "_CARROSSEL|OK|{$when}|{$c['slug']}";
    }
}
foreach ($regras as $palavra => $msg) {
    $q = $pdo->prepare("SELECT id FROM social_auto_reply_rules WHERE UPPER(palavra_chave)=? LIMIT 1");
    $q->execute([$palavra]);
    if ($ja = $q->fetchColumn()) { $out[] = "REGRA_{$palavra}|JA_EXISTE|id=$ja"; continue; }
    $pdo->prepare('INSERT INTO social_auto_reply_rules (palavra_chave, mensagem, ativo, prioridade) VALUES (?, ?, 1, 5)')->execute([$palavra, $msg]);
    $out[] = "REGRA_{$palavra}|CRIADA|id=" . $pdo->lastInsertId();
}
echo implode("\n", $out) . "\n";
